type InterfaceT = Partial<PhysicConnector> &
  Partial<Pick<SubCardT, 'slotId' | 'modelId' | 'rotate'>> & {
    /*接口唯一id  */
    interfaceId?: string | number;
    /** 超级屏业务处理接口所在的设备 */
    sn?: string;
    deviceName?: string;
    deivceIP?: string;

    /**
     * 前端自己生成, 业务需求
     */
    logicInterfaceId?: string;

    /*接口状态 这是我自己定义的属性，不是后台反的，后台要经过好几个字段才能确定 接口的状态*/
    state?: InterfaceStatusE;

    /** 后台返回的接口连接状态 */
    linkState?: LinkStateE;

    /**st2110光口的接口状态 */
    connectionState?: LinkStateE;

    /** 以下接口 现在是可选的 ，未来 从后端请求数据后肯定都是能拿到的 ，到时候 改成 必选的 */
    /*接口的详细信息目前是模拟的*/
    interfaceIdObj?: InterfaceIdObjT;

    /** 辅助信息 */
    auxiliaryInfo?: AuxiliaryInfoT;
    copyInfo?: CopyInfoT;
    capacityMode?: InterfaceCapacityTypeE;

    /** 接口general信息 */
    general?: GeneralT;

    /** 预设缩略timing */
    presetThumbTiming?: PresetThumbTimingT;

    /** 真实缩略timing */
    actualThumbTiming?: ActualThumbTimingT;

    /** 接口预设时序详细信息 */
    presetTiming?: PresetTimingT;

    /** 接口真实时序详细信息 */
    actualTiming?: ActualTimingT;

    /** 接口timing使用类型 */
    timingSelect?: TimingSelectT;

    /** 接口画质 */
    imageQuality?: ImageQualityT;

    /** 接口截取信息。为了保证接口截取后，截取的比例不会被源的实际大小影响，使用截取比例。比例放大100000倍，是因为目前的最大8192宽，对应截取最小64，放大比例大于8192/64=128倍即可保证误差小于1，100000倍可适配分辨率为640 000。    widthResolution表示当前接口的分辨率宽度，heightResolution表示当前接口的分辨率高度。 width表示截取到实际宽度，height表示截取到实际高度。 计算宽高和xy的时候全部采用四舍五入的方式 */
    crop?: CropT;

    /** HDCP设置 */
    hdcp?: HdcpT;

    /** 光口拉流信息 */
    streamInfo?: StreamInfoT;

    /** 文件信息 */
    fileInfo?: InterfaceFileT;

    /**光口IP信息 */
    netInfo?: InterfaceNetWorkT;

    /** 颜色空间 */
    colorSpace?: ColorSpaceT;

    /** 颜色位深 */
    colorDepth?: ColorDepthT;

    /** 颜色变化范围 */
    colorRange?: ColorRangeT;

    /** 色域 */
    colorGamut?: ColorGamutT;

    /** 动态范围 */
    colorDynamicRange?: ColorDynamicRangeT;

    /** 测试画面 */
    testPattern?: TestPatternT;

    /** 3G SDI的smpteMapping设置 */
    smpteMapping?: SmpteMappingT;

    /** 接口自动去隔行设置 */
    removeInterlace?: RemoveInterlaceT;

    /** 接口抠图 */
    cutout?: CutoutT;

    /** 接口HDR属性 接口HDR属性 */
    hdr?: HdrT;

    /** 接口工作模式 */
    workMode?: InterfaceWorkModeE;

    /** 是否支持编辑 */
    disabledAttribute?: boolean;

    /** 截取源列表 */
    crops?: CropsT[];

    /** 截取源信息 */
    cropInfo?: CropsT;
    cropInfoRect?: {
      rect: RectProps & { sourceW: number; sourceH: number };
    }; // 源回显使用
    groupId?: number;
    cropIdObj?: CropIdObjT;
    cropId?: number;
    slotName?: string; // 接口的槽位号
    sourceDisabled?: boolean; // 输入源是否禁止拖拽
    isInterlace?: boolean;
    /** timing信息 */
    thumbTiming?: ThumbTimingT;
    metadata?: MetaDataT[];
    /** 老化整机检测是否通过 */
    machineTestState?: MachineTestInterfaceStatusE;
    /** 按键位置 */
    keyPosition?: number[];
    /** 输入接口兼容模式 */
    compatibilityMode?: EnableE;
    ledHdr?: HDRParamsT;
    networkSourceId?: number; // 网络源sourceId
    reverseControl?: {
      ip: string;
      port: number;
      enable: EnableE;
    };
    audio?: AudioT;
    // 同步设置，同步源分组名称
    sourceGroupName?: string;
    /**3D信息数据 */
    threeD?: {
      actualSource?: {
        sourceFormat: Interface3DFormatE;
      };
      presetSource?: ThreeDInitialValue;
    };
    genlock?: GenlockT;
    /**接口组数据 */
    interfaceGroup?: InterfaceGroupItemT[];
    /** link信息 */
    linkInfo?: LinkInfoT;
    /** 输入驱动参数 */
    inputDriver?: {
      driverMode: number; // 摆幅/预加重模式: 0-自适应, 1-驱动增强
      swingLevel: number; // 摆幅档位: 1-16, 默认1档
      CDRLevel: number; // CDR增强档位: 1-16, 默认1档
      EQLevel: number; // EQ补偿调节档位: 1-16, 默认1档
    };
    /** HDMI输出模式 */
    hdmiOutputMode?: number; // 0=Auto, 1=DVI, 2=HDMI, 3=FORCE_DVI, 4=FORCE_HDMI
    SSRC?: number; //同步源标识
    packetType?: number; //包类型
    packetReadSchedual?: number; //流量整形
    packetMode?: number; //报文封装
    actualHdr?: HdrT;
  };
